const $=s=>document.querySelector(s);
const paths={sliders:'M4 6h16M4 18h16M8 3v6M16 15v6M4 12h16M13 9v6',focus:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5M8 12h8M12 8v8',play:'m9 5 11 7-11 7Z',new:'M12 4v16M4 12h16',volume:'m11 5-6 5H2v4h3l6 5ZM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',arrow:'M12 19V5m-6 6 6-6 6 6',close:'m6 6 12 12M6 18 18 6',stop:'M6 6h12v12H6Z'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.volume}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const state={key:'',chatModel:'openrouter/free',ttsModel:'fish-audio/s2.1-pro-free:free',ttsEngine:'openrouter',routerVoice:'',browserVoice:'',readAloud:true,messages:[],busy:false,controller:null,audio:null,source:null,context:null,speechId:0,chatEpoch:0,recording:false};
let avatar=null, recognition=null,viVoices=[],ttsModels=[];
// Chat and settings remain usable if WebGL or the 3D module is unavailable.
import('./avatar.js').then(({DragonAvatar})=>{try{avatar=new DragonAvatar();window.dragonAvatar=avatar;}catch{avatarError();}}).catch(avatarError);
function avatarError(){$('#loadingText').textContent='Thiết bị chưa hiển thị được rồng 3D';$('#loading small').textContent='Bạn vẫn có thể chat và nghe câu trả lời.';$('#loading .loader').hidden=true;}
function notify(message){$('#notice').textContent=message;$('#notice').hidden=!message;}
function connected(){const yes=!!state.key;$('#keyDot').classList.toggle('connected',yes);$('#connectionStatus').textContent=yes?'Đã kết nối OpenRouter':'Chưa kết nối AI';$('#settingsButton').querySelectorAll('span')[1].textContent=yes?'Cài đặt':'Kết nối AI';$('#connectionHint').hidden=yes;}
function refreshVoiceFields(){$('#routerVoiceFields').hidden=$('#ttsEngine').value!=='openrouter';$('#browserVoiceFields').hidden=$('#ttsEngine').value!=='browser';}
function openSettings(){$('#apiKey').value=state.key;$('#chatModel').value=state.chatModel;$('#ttsEngine').value=state.ttsEngine;$('#ttsModel').value=state.ttsModel;$('#routerVoice').value=state.routerVoice;$('#settingsError').hidden=true;refreshVoiceFields();$('#settingsDialog').showModal();}
$('#settingsButton').onclick=openSettings;
$('#creditsButton').onclick=()=>$('#creditsDialog').showModal();
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$('#ttsEngine').onchange=refreshVoiceFields;
$('#ttsModel').onchange=()=>{const m=ttsModels.find(m=>m.id===$('#ttsModel').value);$('#routerVoice').value=m?.supported_voices?.[0]||'';$('#routerVoice').placeholder=m?.supported_voices?.length?'Ví dụ: '+m.supported_voices.slice(0,3).join(', '):'Để trống để dùng giọng mặc định';};
$('#settingsForm').onsubmit=e=>{e.preventDefault();const key=$('#apiKey').value.trim();const model=$('#chatModel').value.trim();if(key&&!key.startsWith('sk-or-')){$('#settingsError').textContent='Key OpenRouter thường bắt đầu bằng sk-or-. Hãy kiểm tra lại.';$('#settingsError').hidden=false;return;}if(!model){$('#settingsError').textContent='Hãy nhập mã model trò chuyện.';$('#settingsError').hidden=false;return;}
  Object.assign(state,{key,chatModel:model,ttsEngine:$('#ttsEngine').value,ttsModel:$('#ttsModel').value,routerVoice:$('#routerVoice').value.trim(),browserVoice:$('#browserVoice').value});
  $('#apiKey').value='';$('#settingsDialog').close();connected();notify(key?'Đã lưu kết nối trong tab này. Gửi một lời chào để bắt đầu.':'Đã lưu tùy chọn giọng đọc. Chat cần API key OpenRouter.');};
$('#disconnectButton').onclick=()=>{stopSpeech();state.chatEpoch++;state.controller?.abort();state.controller=null;setBusy(false);document.querySelectorAll('.pending').forEach(m=>m.remove());state.key='';$('#apiKey').value='';connected();$('#settingsDialog').close();notify('Đã xóa API key khỏi tab này.');};
function loadBrowserVoices(){viVoices=window.speechSynthesis?.getVoices().filter(v=>/^vi(?:-|_)/i.test(v.lang))||[];const select=$('#browserVoice');const current=select.value;select.replaceChildren();for(const v of viVoices){const o=document.createElement('option');o.value=v.voiceURI;o.textContent=v.name;select.append(o);}if(!viVoices.length){const o=document.createElement('option');o.value='';o.textContent='Chưa tìm thấy giọng tiếng Việt';select.append(o);}else if(viVoices.some(v=>v.voiceURI===current))select.value=current;$('#browserVoiceNote').textContent=viVoices.length?'Dùng giọng có sẵn của thiết bị, không cần key TTS.':'Thiết bị này chưa cung cấp giọng vi-VN cho trang web. Chọn OpenRouter hoặc cài thêm giọng tiếng Việt.';}
loadBrowserVoices();window.speechSynthesis?.addEventListener('voiceschanged',loadBrowserVoices);
async function loadTtsModels(){try{const local=await fetch('./assets/free-tts-models.json');const data=await local.json();setTtsModels(data.data);}catch{}
  try{const r=await fetch('https://openrouter.ai/api/v1/models?output_modalities=speech',{signal:AbortSignal.timeout(10000)});if(r.ok){const data=await r.json();setTtsModels(data.data);}}catch{}}
function setTtsModels(models){ttsModels=models.filter(m=>m.id.endsWith(':free')&&Number(m.pricing?.prompt)===0&&Number(m.pricing?.completion)===0&&(!m.expiration_date||new Date(m.expiration_date)>new Date()));const select=$('#ttsModel');const current=select.value;select.replaceChildren();for(const m of ttsModels){const o=document.createElement('option');o.value=m.id;o.textContent=m.name;select.append(o);}if(!ttsModels.some(m=>m.id===state.ttsModel)){state.ttsModel=ttsModels[0]?.id||'';}select.value=ttsModels.some(m=>m.id===current)?current:state.ttsModel;}
loadTtsModels();

function addMessage(role,text,{pending=false}={}){const node=document.createElement('article');node.className='message '+role+(pending?' pending':'');const label=document.createElement('span');label.className='message-author';label.textContent=role==='user'?'BẠN':'LONG VÂN ✦';const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=text;node.append(label,bubble);$('#messages').append(node);scrollChat();return node;}
function addReadButton(node,text){const b=document.createElement('button');b.className='read-message';b.innerHTML=icon('volume');const label=document.createElement('span');label.textContent='Nghe lại';b.append(label);b.onclick=()=>speak(text);node.append(b);}
function scrollChat(){const el=$('#messages');el.scrollTop=el.scrollHeight;}
function setBusy(busy){state.busy=busy;$('#sendButton').setAttribute('aria-label',busy?'Dừng tạo câu trả lời':'Gửi tin nhắn');$('#sendButton').innerHTML=icon(busy?'stop':'arrow');$('#inputHint').textContent=busy?'Đang trả lời…':'Enter để gửi';}
async function routerError(response){let message='';try{const body=await response.json();message=typeof body.error==='string'?body.error:body.error?.message||'';}catch{}const messages={401:'API key chưa hợp lệ hoặc đã hết hạn. Mở Cài đặt để thay key.',402:'OpenRouter yêu cầu kiểm tra số dư hoặc hạn mức tài khoản.',429:'Model đang giới hạn lượt dùng. Đợi một lúc rồi gửi lại.'};return new Error(messages[response.status]||message||`OpenRouter trả về lỗi ${response.status}.`);}
const headers=()=>({'Authorization':'Bearer '+state.key,'Content-Type':'application/json','X-OpenRouter-Title':'Long Van Dragon Chat'});
async function send(text){text=text.trim();if(!text)return;if(state.busy){state.controller?.abort();return;}if(!state.key){notify('Kết nối OpenRouter trước khi gửi tin nhắn.');openSettings();return;}
  stopRecognition();stopSpeech();notify('');$('#suggestions').hidden=true;$('#chatInput').value='';$('#chatInput').style.height='auto';addMessage('user',text);state.messages.push({role:'user',content:text});setBusy(true);
  const epoch=++state.chatEpoch;const pending=addMessage('assistant','Long Vân đang nghĩ…',{pending:true});let reply='';state.controller=new AbortController();const controller=state.controller;const timer=setTimeout(()=>controller.abort(new Error('OpenRouter phản hồi quá lâu. Hãy thử gửi lại.')),90000);
  try{const body={model:state.chatModel,messages:[{role:'system',content:'Bạn là Long Vân, một người bạn rồng thân thiện nói tiếng Việt tự nhiên. Trả lời ngắn gọn, rõ ràng, ấm áp, thường từ 2 đến 5 câu. Khi cần có thể giải thích kỹ hơn. Không tự xưng là người thật. Không giả vờ có khả năng thực hiện thao tác ngoài cuộc trò chuyện. Hạn chế Markdown vì câu trả lời có thể được đọc thành tiếng.'},...state.messages.slice(-20)],stream:true,max_tokens:700};
    const response=await fetch('https://openrouter.ai/api/v1/chat/completions',{method:'POST',headers:headers(),body:JSON.stringify(body),signal:state.controller.signal});if(!response.ok)throw await routerError(response);
    if(!response.body)throw new Error('Không nhận được nội dung từ OpenRouter.');
    if((response.headers.get('content-type')||'').includes('application/json')){const data=await response.json();reply=data.choices?.[0]?.message?.content||'';pending.querySelector('.bubble').textContent=reply;}
    else{const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
      const parseLine=line=>{if(!line.startsWith('data:'))return;const data=line.slice(5).trim();if(!data||data==='[DONE]')return;let packet;try{packet=JSON.parse(data);}catch{return;}if(packet.error)throw new Error(packet.error.message||'OpenRouter gặp lỗi khi trả lời.');const part=packet.choices?.[0]?.delta?.content;if(typeof part==='string'){reply+=part;pending.classList.remove('pending');pending.querySelector('.bubble').textContent=reply;scrollChat();}};
      while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split('\n');buffer=lines.pop();for(const line of lines)parseLine(line.replace(/\r$/,''));}buffer+=decoder.decode();if(buffer.trim())parseLine(buffer.trim());}
    if(epoch!==state.chatEpoch)return;if(!reply.trim())throw new Error('Model chưa trả lời bằng chữ. Hãy thử model chat khác.');state.messages.push({role:'assistant',content:reply});pending.classList.remove('pending');addReadButton(pending,reply);if(state.readAloud&&state.ttsEngine!=='off')speak(reply);
  }catch(error){if(epoch!==state.chatEpoch)return;pending.classList.remove('pending');if(reply.trim()){pending.querySelector('.bubble').textContent=reply+'\n\n[Đã dừng trả lời]';state.messages.push({role:'assistant',content:reply});addReadButton(pending,reply);}else{pending.remove();state.messages.pop();}if(error.name==='AbortError')notify('Đã dừng tạo câu trả lời.');else notify(error.message||'Chưa kết nối được OpenRouter. Kiểm tra mạng và thử lại.');}
  finally{clearTimeout(timer);if(epoch===state.chatEpoch){state.controller=null;setBusy(false);scrollChat();}}}
$('#chatForm').onsubmit=e=>{e.preventDefault();if(state.busy)state.controller?.abort();else send($('#chatInput').value);};
$('#chatInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(!state.busy)send(e.currentTarget.value);}};
$('#chatInput').oninput=e=>{e.target.style.height='auto';e.target.style.height=Math.min(125,e.target.scrollHeight)+'px';};
$('#suggestions').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(!state.key)$('#chatInput').value=b.textContent;send(b.textContent);});
$('#clearButton').onclick=()=>{state.chatEpoch++;state.controller?.abort();state.controller=null;setBusy(false);stopRecognition();stopSpeech();state.messages=[];document.querySelectorAll('#messages .message:not(.intro)').forEach(m=>m.remove());$('#suggestions').hidden=false;notify('Đã mở cuộc trò chuyện mới.');};

function stopSpeech(){state.speechId++;state.audio?.pause();if(state.audio){state.audio.removeAttribute('src');state.audio.load();state.audio=null;}try{state.source?.stop();}catch{}state.source=null;window.speechSynthesis?.cancel();if(state.context){state.context.close().catch(()=>{});state.context=null;}avatar?.endSpeech();$('#stopSpeech').disabled=true;}
function speechText(text){return text.replace(/```[\s\S]*?```/g,' ').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1').replace(/[#*`_>]/g,'').slice(0,5000);}
async function speak(raw,{sample=false}={}){stopSpeech();const id=state.speechId;const text=speechText(raw);if(!text)return;notify('');$('#stopSpeech').disabled=false;
  const finish=()=>{if(id===state.speechId){avatar?.endSpeech();$('#stopSpeech').disabled=true;}};
  try{if(state.ttsEngine==='off'){notify('Giọng đọc đang tắt. Bạn có thể bật trong Cài đặt.');finish();return;}
    if(state.ttsEngine==='browser'||(!state.key&&sample)){loadBrowserVoices();const voice=viVoices.find(v=>v.voiceURI===state.browserVoice)||viVoices[0];if(!voice)throw new Error('Máy chưa có giọng tiếng Việt cho trang web. Kết nối OpenRouter để thử TTS miễn phí.');const u=new SpeechSynthesisUtterance(text);u.voice=voice;u.lang='vi-VN';u.rate=.95;u.onstart=()=>{if(id===state.speechId)avatar?.beginSpeech();};u.onend=finish;u.onerror=e=>{finish();if(!['canceled','interrupted'].includes(e.error))notify('Chưa đọc được bằng giọng trình duyệt. Thử chọn OpenRouter trong Cài đặt.');};speechSynthesis.speak(u);return;}
    if(!state.key){finish();notify('Kết nối OpenRouter để nghe giọng rồng.');openSettings();return;}
    if(!state.ttsModel)throw new Error('Hiện chưa tìm thấy model TTS miễn phí. Bạn có thể dùng giọng trình duyệt.');
    notify('Đang tạo giọng nói…');
    const Context=window.AudioContext||window.webkitAudioContext;const context=Context?new Context():null;if(context){state.context=context;await context.resume();}
    const payload={model:state.ttsModel,input:text,response_format:'mp3'};if(state.routerVoice)payload.voice=state.routerVoice;
    const response=await fetch('https://openrouter.ai/api/v1/audio/speech',{method:'POST',headers:headers(),body:JSON.stringify(payload),signal:AbortSignal.timeout(60000)});if(!response.ok)throw await routerError(response);const bytes=await response.arrayBuffer();if(id!==state.speechId)return;if(bytes.byteLength<20)throw new Error('Model TTS chưa trả về âm thanh.');
    if(context){const decoded=await context.decodeAudioData(bytes);if(id!==state.speechId)return;const source=context.createBufferSource();const analyser=context.createAnalyser();analyser.fftSize=256;source.buffer=decoded;source.connect(analyser);analyser.connect(context.destination);state.source=source;source.onended=()=>{finish();if(state.context===context){state.context=null;context.close().catch(()=>{});}};avatar?.beginSpeech(analyser);source.start();notify('');}
    else{const url=URL.createObjectURL(new Blob([bytes],{type:'audio/mpeg'}));const audio=new Audio(url);state.audio=audio;audio.onended=()=>{URL.revokeObjectURL(url);finish();};audio.onerror=()=>{URL.revokeObjectURL(url);finish();notify('Trình duyệt chưa phát được audio này.');};await audio.play();avatar?.beginSpeech();notify('');}
  }catch(error){if(id!==state.speechId)return;stopSpeech();notify(error.name==='TimeoutError'?'Tạo giọng nói quá lâu. Bạn có thể thử lại hoặc chọn giọng trình duyệt.':error.message||'Chưa tạo được giọng nói. Phần chat vẫn dùng được.');}}
$('#stopSpeech').onclick=()=>{stopSpeech();notify('Đã dừng đọc.');};
$('#voiceToggle').onclick=()=>{state.readAloud=!state.readAloud;$('#voiceToggle').setAttribute('aria-pressed',String(state.readAloud));if(!state.readAloud)stopSpeech();};
$('#testVoice').onclick=()=>speak('Xin chào! Mình là Long Vân, người bạn rồng của bạn. Hôm nay bạn muốn kể cho mình nghe điều gì?',{sample:true});

const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
function stopRecognition(){if(recognition&&state.recording)try{recognition.stop();}catch{}state.recording=false;$('#micButton').setAttribute('aria-pressed','false');$('#micLabel').textContent='Nói chuyện';}
if(Recognition){recognition=new Recognition();recognition.lang='vi-VN';recognition.continuous=false;recognition.interimResults=true;
  recognition.onstart=()=>{state.recording=true;$('#micButton').setAttribute('aria-pressed','true');$('#micLabel').textContent='Đang nghe…';notify('Nói bằng tiếng Việt. Bấm micro lần nữa để dừng và chỉnh tin nhắn trước khi gửi.');};
  recognition.onresult=e=>{let text='';for(let i=0;i<e.results.length;i++)text+=e.results[i][0].transcript;$('#chatInput').value=text;$('#chatInput').dispatchEvent(new Event('input'));};
  recognition.onend=()=>{stopRecognition();if($('#chatInput').value.trim())notify('Đã nhận lời nói. Bấm gửi khi bạn sẵn sàng.');};
  recognition.onerror=e=>{stopRecognition();const errors={'not-allowed':'Micro chưa được cho phép. Cấp quyền micro cho trang hoặc gõ tin nhắn.','no-speech':'Chưa nghe thấy giọng nói. Bấm micro để thử lại.','network':'Nhận giọng nói cần kết nối mạng. Bạn có thể gõ tin nhắn.','audio-capture':'Không tìm thấy micro. Kiểm tra thiết bị ghi âm.'};notify(errors[e.error]||'Chưa nhận được lời nói. Thử lại hoặc gõ tin nhắn.');};
}
$('#micButton').onclick=()=>{if(!recognition){notify('Trình duyệt này chưa hỗ trợ nhập giọng nói. Thử Chrome hoặc Edge, hoặc gõ tin nhắn.');return;}if(state.recording){stopRecognition();return;}stopSpeech();try{recognition.start();}catch{notify('Micro đang bận. Đợi một chút rồi thử lại.');}};
$('#cameraButton').onclick=()=>avatar?.toggleCamera();$('#motionButton').onclick=()=>{if(!avatar?.ready){notify('Đợi rồng tải xong để bật chuyển động.');return;}const active=avatar.toggleMotion();$('#motionButton').setAttribute('aria-pressed',String(active));$('#motionButton').title=active?'Tắt chuyển động cơ thể':'Bật chuyển động cơ thể';};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopRecognition();});
addEventListener('pagehide',()=>{state.key='';$('#apiKey').value='';state.controller?.abort();stopRecognition();stopSpeech();});
connected();
